"""Negotiation workspace: comparison, live stock explanation and decision evidence."""
CSS='''
[data-view=propuestas].po-guided:has(#po-conditions:not([hidden])) .po-workspace{display:block}
#po-conditions{--po-condition-columns:minmax(120px,.65fr) minmax(120px,.65fr) repeat(2,minmax(190px,1fr));font-family:var(--eios-font)!important;background:transparent;border:0;padding:0}
#po-conditions>.po-heading{background:var(--guide-surface,#fff);border:1px solid var(--guide-border,#dce4f2);border-radius:18px;padding:22px;margin-bottom:0}
#po-conditions .po-heading h2{font-family:var(--eios-display)!important;text-transform:none;font-size:25px!important}
#po-conditions #po-draft-negotiation{grid-template-columns:var(--po-condition-columns);min-width:680px}
#po-negotiation-review-row{display:grid;grid-template-columns:var(--po-condition-columns);align-items:start;min-width:680px;margin:0 8px 12px}
#po-negotiation-review-row #po-option-studies{grid-column:3/5;margin:0;padding:0;border:0;background:transparent;min-width:0}
#po-negotiation-review-row .po-option-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0}
#po-negotiation-review-row #po-option-studies>h3,#po-negotiation-review-row #po-option-studies>p,#po-negotiation-review-row .po-option-card>h4,#po-negotiation-review-row .po-option-card>small,#po-negotiation-review-row .po-option-card>strong,#po-negotiation-review-row .po-option-card>span{display:none}
#po-negotiation-review-row .po-option-card{margin:0 8px;padding:0;border:0;border-radius:0;background:transparent}
#po-negotiation-review-row .po-option-card button{width:100%;font-size:12px;min-height:38px;margin:5px 0}
#po-negotiation-review-row .po-option-verdict{font-size:12px;padding:10px;margin:6px 0}
#po-negotiation-review-row .po-option-detail{grid-column:1/-1;margin-top:16px}
#po-condition-evidence{margin-top:22px}
#po-condition-evidence>h3,.po-evidence-caption{font-size:11px!important;letter-spacing:.1em;color:var(--guide-muted,#596b87);margin:22px 4px 12px}
#po-condition-evidence #po-purchase-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;background:transparent;border:0;padding:0;margin:0}
#po-condition-evidence #po-purchase-summary>h3,#po-condition-evidence #po-purchase-summary>dl,#po-condition-evidence #po-purchase-summary>.po-option-context{display:none}
#po-condition-evidence #po-purchase-summary>.verdict,#po-condition-evidence #po-purchase-summary>.po-summary-stock,#po-condition-evidence #po-purchase-summary>p:has(.po-summary-action){margin:0;padding:22px;border:1px solid var(--guide-border,#dce4f2);border-radius:16px;background:var(--guide-surface,#fff);min-height:110px;font-size:14px}
#po-condition-evidence #po-purchase-summary>p:has(>.po-summary-action):not(.po-summary-stock){background:#0b1b3e;color:white}
#po-condition-evidence #po-purchase-summary>details,#po-condition-evidence #po-purchase-summary>p:last-child{grid-column:1/-1}
#po-evidence-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;align-items:start;margin:16px 0}
.po-evidence-card,#po-scenario-calendar{min-width:0;border:1px solid var(--guide-border,#dce4f2);border-radius:18px;background:var(--guide-surface,#fff);padding:20px;box-shadow:0 5px 20px #13264c06}
.po-evidence-card h3,#po-scenario-calendar h3{font-family:var(--eios-display);font-size:19px!important;margin:0 0 14px}
.po-evidence-card #po-cash,.po-evidence-card #po-alternatives-table{margin:0;border:0;padding:0;background:transparent}
.po-evidence-card .po-option-context{font-size:12px}
.po-evidence-card .po-cash-grid{grid-template-columns:1fr!important}
#po-scenario-events{display:flex;align-items:stretch;gap:0;overflow-x:auto;padding:18px 0}
.po-scenario-event{flex:1;min-width:125px;border-top:4px solid #2154f5;padding:18px 10px 0;position:relative;font-size:12px;text-align:center}
.po-scenario-event:before{content:'';position:absolute;top:-8px;left:calc(50% - 6px);width:12px;height:12px;background:var(--guide-surface,#fff);border:2px solid #11264a;border-radius:50%}
.po-scenario-event strong,.po-scenario-event span{display:block}.po-scenario-event span{color:var(--guide-muted,#596b87);margin-top:6px}
#po-stock-evidence dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:0}
#po-stock-evidence dl>div{padding:12px;background:var(--guide-soft,#f4f6fb);border:1px solid var(--guide-border,#dce4f2);border-radius:12px}
#po-stock-evidence dt{font-size:11px;color:var(--guide-muted,#596b87)}#po-stock-evidence dd{margin:8px 0 0;font-size:19px;font-family:var(--eios-display);font-weight:600}
.po-evidence-limit{font-size:12px;line-height:1.6;padding:12px;background:var(--guide-soft,#f4f6fb);border-radius:10px}
#po-condition-context{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));border:1px solid var(--guide-border,#dce4f2);border-top:0;border-radius:0 0 16px 16px;margin:-8px 0 16px;padding:16px;background:var(--guide-surface,#fff);gap:16px;font-size:12px}
#po-condition-context small{display:block;letter-spacing:.07em;font-size:9px;color:var(--guide-muted,#596b87);margin-bottom:5px}
#po-condition-evidence #po-study-state{margin-top:16px}
@media(max-width:1100px){#po-evidence-cards{grid-template-columns:1fr}#po-condition-evidence #po-purchase-summary{grid-template-columns:1fr}#po-condition-context{grid-template-columns:repeat(2,minmax(0,1fr))}}
'''
JS=r'''
(function(){
 const conditions=$('po-conditions'),aside=document.querySelector('[data-view=propuestas] .po-context'),panel=$('po-option-studies'),table=conditions.querySelector('.po-negotiation-scroll'),cash=$('po-cash'),alternatives=$('po-alternatives-table'),summary=$('po-purchase-summary'),study=$('po-study-state');
 const homes=new Map();for(const node of [aside,panel,cash,alternatives,summary,study]){const marker=document.createComment('negotiation evidence home');node.before(marker);homes.set(node,marker)}
 const row=document.createElement('div');row.id='po-negotiation-review-row';table.after(row);
 const context=document.createElement('div');context.id='po-condition-context';conditions.querySelector('.po-heading').after(context);
 const evidence=document.createElement('section');evidence.id='po-condition-evidence';const title=document.createElement('h3');title.textContent='ESTADO DE LA PROPUESTA';evidence.append(title);
 const calendar=document.createElement('section');calendar.id='po-scenario-calendar';const ch=document.createElement('h3');ch.textContent='Calendario del escenario';const events=document.createElement('div');events.id='po-scenario-events';const note=document.createElement('p');note.className='po-evidence-limit';note.textContent='Fechas de referencia e hipótesis declaradas. No acreditan una entrega ni la aceptación de condiciones.';calendar.append(ch,events,note);
 const cards=document.createElement('div');cards.id='po-evidence-cards';function card(name,id){const box=document.createElement('section');box.className='po-evidence-card';box.id=id;const h=document.createElement('h3');h.textContent=name;box.append(h);cards.append(box);return box}const moneyCard=card('Dinero','po-money-evidence'),stockCard=card('Stock','po-stock-evidence'),alternativesCard=card('Alternativas','po-alternatives-evidence');const moneyBody=document.createElement('div');moneyCard.append(moneyBody);const altCount=document.createElement('p');altCount.className='po-evidence-limit';const altDetails=document.createElement('details'),altTitle=document.createElement('summary');altTitle.textContent='Ver alternativas y fuentes del cálculo';altDetails.append(altTitle);alternativesCard.append(altCount,altDetails);const moneyDetails=document.createElement('details'),moneyTitle=document.createElement('summary');moneyTitle.textContent='Ver gráfico, pagos y comprobaciones';moneyDetails.append(moneyTitle);moneyCard.append(moneyDetails);const stockBody=document.createElement('div');stockCard.append(stockBody);const contrasts=document.createElement('section');contrasts.id='po-source-contrasts';contrasts.className='po-evidence-limit';evidence.append(calendar,cards,contrasts);$('po-guide-analysis').before(evidence);

 function update(r){const form=$('form'),s=r?.stock_planning,a=s?.assumptions||{},v=form.elements;context.replaceChildren();for(const [name,value]of [['Cantidad',(v.quantity.value||'—')+(r?.current_terms?.unit?' '+r.current_terms.unit:'')],['Corte de datos',r?.cutoff?stockDate(r.cutoff):state?.info?.as_of_date?stockDate(state.info.as_of_date):'Pendiente'],['Horizonte analizado',r?.horizon_end?(stockDate(r.cutoff)+' → '+stockDate(r.horizon_end)):'Pendiente'],['Referencia',v.reference?.value||'Sin guardar'],['Responsable',a.actor||'Sin declarar']]){const item=document.createElement('div'),label=document.createElement('small'),strong=document.createElement('strong');label.textContent=name;strong.textContent=value;item.append(label,strong);context.append(item)}
 events.replaceChildren();for(const [label,date]of [['Corte de datos',r?.cutoff],['Pedido',a.order_date||v.order_date.value],['Recepción prevista',s?.arrival_date],['Vencimiento de mercancía',r?.current_terms?.due_date],['Fin de cobertura',s?.target_end],['Fin del horizonte',r?.horizon_end]]){const item=document.createElement('div');item.className='po-scenario-event';const strong=document.createElement('strong'),text=document.createElement('span');strong.textContent=date?(String(date).includes('/')?date:stockDate(date)):'Pendiente';text.textContent=label;item.append(strong,text);events.append(item)}
 altCount.textContent=r?((r.alternatives||[]).length+' opciones calculadas frente a la propuesta analizada. Ninguna se aplica automáticamente.'):'Opciones pendientes de cálculo. Completa los datos del escenario.';moneyBody.replaceChildren();for(const [label,value]of [['Saldo mínimo previsto',r?.scenario?.minimum_balance],['Reserva mínima',r?.treasury_minimum],['Falta para respetar la reserva',r?.scenario?.deficit],['Tesorería al inicio',r?.opening_balance]]){const p=document.createElement('p');p.className='po-money-fact';const dt=document.createElement('span'),dd=document.createElement('strong');dt.textContent=label;dd.textContent=value==null?'Pendiente':money(value)+' €';p.append(dt,dd);moneyBody.append(p)}
 stockBody.replaceChildren();const dl=document.createElement('dl');for(const [label,value]of [['Stock libre al inicio',a.available_at_order],['Consumo diario adicional',a.daily_demand],['Stock de seguridad',a.safety_stock],['Plazo de recepción (días)',a.lead_time_days],['Cobertura objetivo (días)',a.target_days],['Compra para el objetivo',s?.scenario_quantity]]){const item=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value===undefined?'Pendiente':stockNumber(value);item.append(dt,dd);dl.append(item)}stockBody.append(dl);const ref=r?.quantity_review;contrasts.replaceChildren();const differences=[['Consumo diario',a.daily_demand,ref?.coverage?.daily_demand,'La previsión de referencia y el consumo adicional declarado pueden tener distinto alcance.'],['Stock al inicio del pedido',a.available_at_order,ref?.inventory?.available,'El inventario corresponde a su fecha; documenta los movimientos hasta el pedido.'],['Seguridad y mínimo de referencia',a.safety_stock,ref?.minimum?.value,'Son conceptos distintos; la diferencia no demuestra un error.']].filter(([,x,y])=>x!=null&&y!=null&&Number(x)!==Number(y));contrasts.hidden=!differences.length;if(differences.length){const h=document.createElement('h3');h.textContent='Referencias que debes contrastar';contrasts.append(h);for(const [label,x,y,explanation]of differences){const p=document.createElement('p');p.textContent=label+': escenario '+stockNumber(x)+' · referencia '+stockNumber(y)+'. '+explanation;contrasts.append(p)}}if(ref){const details=document.createElement('details'),heading=document.createElement('summary');heading.textContent='Inventario y mínimo de referencia';details.append(heading);for(const [label,value]of [['Disponible al inventario',ref.inventory?.available],['Reservado, ya descontado',ref.inventory?.reserved],['Mínimo de referencia',ref.minimum?.value]]){const p=document.createElement('p');p.textContent=label+': '+(value==null?'Pendiente':stockNumber(value));details.append(p)}const scope=document.createElement('p');scope.textContent='El inventario es una referencia a su fecha. El stock libre al pedido y la seguridad son supuestos del escenario; pueden diferir y requieren soporte.';details.append(scope);stockBody.append(details)}const limit=document.createElement('p');limit.className='po-evidence-limit';limit.textContent=r?.purchase_summary?.stock?.message||'Completa y confirma la planificación para calcular el escenario de stock.';stockBody.append(limit);const go=document.createElement('button');go.type='button';go.textContent='Revisar stock, consumo y plazos →';go.onclick=()=>purchaseGuideNavigate('po-references',true);stockBody.append(go);
 }
 function place(){const active=document.body.dataset.purchaseMode!=='saved'&&!conditions.hidden;context.hidden=evidence.hidden=row.hidden=!active;if(active){row.append(panel);moneyDetails.append(cash);altDetails.append(alternatives);title.after(summary);evidence.append(study);aside.hidden=true}else{for(const node of [cash,alternatives,summary,study,panel]){const home=homes.get(node);if(home.parentNode&&(evidence.contains(node)||node.parentElement===row))home.after(node)}aside.hidden=false} }
 const original=renderPurchaseCash;renderPurchaseCash=function(box,r,editable){original(box,r,editable);if(editable&&box.id==='po-cash')update(r)};
 const clear=clearPurchaseSummary;clearPurchaseSummary=function(){clear();update(null)};
 new MutationObserver(place).observe(conditions,{attributes:true,attributeFilter:['hidden']});new MutationObserver(place).observe(document.body,{attributes:true,attributeFilter:['data-purchase-mode']});for(const type of ['input','change'])$('form').addEventListener(type,()=>update(null));update(null);place();
})();
'''

CSS += """
.po-money-fact{display:flex;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid var(--guide-border,#dce4f2);font-size:12px}.po-money-fact strong{font-family:var(--eios-display);font-size:20px;font-variant-numeric:tabular-nums}.po-evidence-card details{font-size:12px;line-height:1.6}#po-condition-evidence #po-study-state[data-mode=draft]{display:none}
"""

CSS += """
#po-condition-evidence #po-purchase-summary>.verdict:before{content:'DINERO';display:block;font-size:10px;letter-spacing:.1em;margin-bottom:12px;color:var(--guide-muted)}
#po-condition-evidence #po-purchase-summary>.po-summary-stock:before{content:'STOCK';display:block;font-size:10px;letter-spacing:.1em;margin:0 0 12px;color:var(--guide-muted)}
#po-condition-evidence #po-purchase-summary[data-status=WITHIN_DECLARED_SCENARIO]>.verdict{border-top:3px solid #08775b}#po-condition-evidence #po-purchase-summary[data-status=SHORTFALL]>.verdict{border-top:3px solid #b22c29}
#po-condition-evidence #po-purchase-summary>.po-summary-stock[data-tone=amber]{border-top:3px solid #dc8b0a}#po-condition-evidence #po-purchase-summary>.po-summary-stock[data-tone=red]{border-top:3px solid #b22c29}#po-condition-evidence #po-purchase-summary>.po-summary-stock[data-tone=green]{border-top:3px solid #08775b}
#po-money-evidence>details{margin-top:16px}.po-evidence-card strong{font-variant-numeric:tabular-nums}#po-conditions .po-column-total strong{font-size:clamp(20px,1.5vw,27px);white-space:nowrap}#po-conditions>.po-heading h2{text-transform:none}
"""
